#!/usr/bin/env bash
# Generated by Eidolons. Receipts carry event/reason codes, never prompt text.
_eidolons_hook_policy="fail-open"
_eidolons_hook_fail() {
  local event="$1" reason="$2" receipt=".eidolons/harness/hook-failures.jsonl"
  mkdir -p "$(dirname "$receipt")" 2>/dev/null || true
  if command -v jq >/dev/null 2>&1; then
    jq -cn --arg event "$event" --arg reason "$reason" --arg policy "$_eidolons_hook_policy" \
      '{event:$event,reason:$reason,policy:$policy}' >> "$receipt" 2>/dev/null || true
  else
    printf '{"event":"%s","reason":"%s","policy":"%s"}\n' "$event" "$reason" "$_eidolons_hook_policy" >> "$receipt" 2>/dev/null || true
  fi
  case "$_eidolons_hook_policy" in
    fail-closed)
      printf '{"continue":false,"stopReason":"Eidolons routing hook failed (%s). Repair the hook or change harness.hook_failure_policy."}\n' "$reason"
      ;;
    warn)
      printf '{"hookSpecificOutput":{"hookEventName":"%s","additionalContext":"Eidolons routing hook failed (%s); routing was not applied."}}\n' "$event" "$reason"
      ;;
    fail-open) return 0 ;;
  esac
}
_eidolons_hook_valid() {
  local event="$1" output="$2"
  printf '%s' "$output" | jq -e --arg e "$event" \
    '.hookSpecificOutput.hookEventName == $e and
     (.hookSpecificOutput.additionalContext | type == "string" and length > 0)' >/dev/null 2>&1
}
_eidolons_hook_qualified() {
  local normalized
  normalized=" $(printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9' ' ') "
  [[ "$normalized" =~ [[:space:]](fix|implement|build|patch|write|change|edit|modify|refactor|delete|create|remove|plan|spec|design|map|trace|audit|investigate|debug|diagnose|release|bump|test|verify)[[:space:]] ]]
}
